{
  "name": "CC-Light 控制器",
  "name_en": "CC-Light Controller",
  "manufacturer": "QuTech",
  "description": "CC-Light 是一台面向量子实验的数字控制与时序控制设备，可通过 SCPI 配置并执行控制存储器与 QISA 相关指令，用于协调触发、序列执行和实验时序管理，常见于超导量子比特测控实验。",
  "description_en": "The CC-Light is a digital control and timing instrument for quantum experiments. It can be configured over SCPI and execute control-store and QISA-related instructions to coordinate triggering, sequence execution, and experimental timing, commonly in superconducting qubit measurement and control setups.",
  "tag_hints": [
    "quantum control",
    "experiment timing",
    "QISA",
    "control store",
    "SCPI instrument",
    "AWG triggering",
    "superconducting qubits"
  ],
  "actions": [
    {
      "action_name": "auto-add_additional_parameters",
      "description": "定义附加的设备专用控制参数。",
      "description_en": "Define additional device-specific control parameters."
    },
    {
      "action_name": "auto-add_standard_parameters",
      "description": "定义标准设备控制参数。",
      "description_en": "Define the standard device control parameters."
    },
    {
      "action_name": "auto-print_control_store",
      "description": "读取并显示设备中的控制存储器内容。",
      "description_en": "Read and display the contents of the device control store."
    },
    {
      "action_name": "auto-print_qisa_opcodes",
      "description": "读取并显示设备支持的 QISA 操作码。",
      "description_en": "Read and display the QISA opcodes supported by the device."
    },
    {
      "action_name": "auto-print_qisa_with_control_store",
      "description": "读取并显示 QISA 指令与控制存储器的对应关系。",
      "description_en": "Read and display the mapping between QISA instructions and the control store."
    },
    {
      "action_name": "auto-print_readable_idn",
      "description": "读取并显示设备身份信息。",
      "description_en": "Read and display the device identification information."
    },
    {
      "action_name": "auto-start",
      "description": "启动设备控制序列运行。",
      "description_en": "Start device sequence execution."
    },
    {
      "action_name": "auto-stop",
      "description": "停止设备控制序列运行。",
      "description_en": "Stop device sequence execution."
    },
    {
      "action_name": "auto-get_idn",
      "description": "获取设备身份信息。",
      "description_en": "Get device identification information."
    },
    {
      "action_name": "auto-getOperationComplete",
      "description": "获取操作完成状态。",
      "description_en": "Get operation-complete status."
    },
    {
      "action_name": "auto-get_operation_complete",
      "description": "获取操作完成状态。",
      "description_en": "Get operation-complete status."
    }
  ]
}

